   567	
   568	        let mut results_by_id =
   569	            FxHashMap::<usize, [SearchResult; MAX_RESULTS]>::with_capacity_and_hasher(
   570	                ground_truth.len(),
   571	                Default::default(),
   572	            );
   573	        for entry in ground_truth {
   574	            if entry.neighbors.len() < MAX_RESULTS {
   575	                continue;
   576	            }
   577	
   578	            let mut results = [SearchResult {
   579	                id: 0,
   580	                distance: 0.0,
   581	            }; MAX_RESULTS];
   582	            for (rank, &id) in entry.neighbors.iter().take(MAX_RESULTS).enumerate() {
   583	                results[rank] = SearchResult {
   584	                    id,
   585	                    distance: rank as f64,
   586	                };
   587	            }
   588	            results_by_id.insert(entry.query_id, results);
   589	        }
