   615	            let response = json_http_response(&body);
   616	            entries_by_query.insert(
   617	                key,
   618	                CachedQueryResult {
   619	                    results,
   620	                    response: response.clone(),
   621	                },
   622	            );
   623	            if let Some(request_key) = RequestCacheKey::from_request_body(&request_body) {
   624	                let tail_start = usize::min(request_body.len(), REQUEST_CACHE_PREFIX);
   625	                let tail = &request_body[tail_start..];
   626	                let candidates = entries_by_request_key.entry(request_key).or_default();
